function Get-Sha256([string]$Path) { $s=[IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read); try {$h=[Security.Cryptography.SHA256]::Create();try{-join($h.ComputeHash($s)|%{$_.ToString('x2')})}finally{$h.Dispose()}}finally{$s.Dispose()} }
function Open-StableReadLock([string]$Path) {
 $fullPath=[IO.Path]::GetFullPath($Path);$stream=[IO.File]::Open($fullPath,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
 try {$memory=New-Object IO.MemoryStream;try{$stream.CopyTo($memory);$bytes=$memory.ToArray()}finally{$memory.Dispose()};$sha=[Security.Cryptography.SHA256]::Create();try{$digest=-join($sha.ComputeHash($bytes)|%{$_.ToString('x2')})}finally{$sha.Dispose()};$utf8=[Text.UTF8Encoding]::new($false,$true);$text=$utf8.GetString($bytes);if($text.Length -gt 0 -and $text[0] -eq [char]0xfeff){$text=$text.Substring(1)};[pscustomobject]@{path=$fullPath;stream=$stream;bytes=$bytes;sha256=$digest;text=$text}}catch{$stream.Dispose();throw}
}
function Open-StableJsonLock([string]$Path,[string]$ExpectedSha256,[string]$Label) {
 $locked=Open-StableReadLock $Path;try{if($locked.sha256 -ne $ExpectedSha256.ToLowerInvariant()){throw "$Label does not match the operator-supplied SHA-256"};$data=$locked.text|ConvertFrom-Json -ErrorAction Stop;$locked|Add-Member -NotePropertyName data -NotePropertyValue $data;return $locked}catch{$locked.stream.Dispose();throw}
}
function Get-StableLock($Locks,[string]$Path) {$key=[IO.Path]::GetFullPath($Path).ToLowerInvariant();if(!$Locks.ContainsKey($key)){throw "No stable read lock exists for $Path"};$Locks[$key]}
function Get-StableSha256($Locks,[string]$Path) {(Get-StableLock $Locks $Path).sha256}
function Get-StableText($Locks,[string]$Path) {(Get-StableLock $Locks $Path).text}
function Write-Lifecycle([hashtable]$e) {$e.timestamp=(Get-Date).ToString('o'); Add-Content -LiteralPath $lifecycle -Value ($e|ConvertTo-Json -Compress -Depth 12) -Encoding UTF8}
function Get-StableAcPowerFacts {
 $b=@(Get-CimInstance -Namespace root\wmi -ClassName BatteryStatus -ErrorAction Stop); if(!$b){throw 'BatteryStatus unavailable'}; $a=@($b|?{$_.Active -eq $true});if(!$a){throw 'No active battery'};foreach($x in $a){if($x.PowerOnline -ne $true -or $x.Critical -ne $false){throw 'Battery is not stable AC/noncritical'}}
 $w=@(Get-CimInstance -ClassName Win32_Battery -ErrorAction Stop);if(!$w){throw 'Win32_Battery unavailable'};foreach($x in $w){if($null -eq $x.EstimatedChargeRemaining -or [double]$x.EstimatedChargeRemaining -le 0 -or @(2,3,6,7,8,11) -notcontains [int]$x.BatteryStatus){throw 'Battery charge status is not AC-compatible'}}; [pscustomobject]@{battery_status=$b;win32_battery=$w}
}
