function Assert-R10Gate { param($Gate,[string]$GateSha256,[string]$LauncherSha256,[string]$RunnerSha256,[string]$ContractSha256,$Locks)
 if($Gate.status -ne 'pass' -or -not $Gate.fresh_launch_authorized -or $Gate.run_id_prefix -ne $prefix -or @($Gate.seeds).Count -ne 2 -or [int]$Gate.seeds[0] -ne 42 -or [int]$Gate.seeds[1] -ne 43 -or (@($Gate.expected_children) -join '|') -ne ($children -join '|')){throw 'Canonical r10 identity binding failed'}
 if($Gate.protocol.protocol_id -ne 'PAPER_TEXT_V1' -or $Gate.protocol.stage3_stability_adaptation_id -ne 'PAPER_TEXT_STAGE3_GLOBAL_NORM_CLIP_V1' -or [double]$Gate.protocol.stage3_gradient_clip_norm -ne 1.0 -or $Gate.protocol.stage3_gradient_clip_application_point -ne 'after_effective_batch_average_before_optimizer_step' -or [int]$Gate.protocol.stage3_gradient_accumulation_steps -ne 128 -or [int]$Gate.protocol.stage3_effective_batch -ne 128 -or [int]$Gate.protocol.stage3_hardware_microbatch -ne 1 -or [double]$Gate.protocol.stage3_learning_rate -ne 0.1){throw 'Canonical r10 stability protocol binding failed'}
 $s=$Gate.source_sha256; foreach($p in @(@($runner,$s.runner_sh),@($multiSeedTest,$s.test_multi_seed_py),@($progressProbe,$s.probe_pilot_progress_ps1),@($processProbe,$s.probe_pilot_process_sh),@($powerGateTest,$s.r10_power_gate_smoke_ps1),@($confirmationGateTest,$s.r10_user_confirmation_gate_smoke_ps1),@($reviewGateTest,$s.r10_review_binding_smoke_ps1),@($livePowerProbe,$s.r10_live_power_gate_probe_ps1),@($lifecycleFailureTest,$s.r10_lifecycle_failure_smoke_ps1),@($probeProgressTest,$s.r10_probe_progress_smoke_ps1),@($launchEvidenceTest,$s.r10_launch_test_evidence_smoke_ps1),@($stableReadRaceTest,$s.r10_stable_read_lock_smoke_ps1),@($importClosureTest,$s.r10_import_closure_smoke_ps1),@($sourceManifest,$s.source_manifest_json),@($environmentManifest,$s.environment_manifest_json),@($r8Evidence,$s.r8_verification_evidence_json),@($multiSeedEvidence,$s.multi_seed_implementation_evidence_json),@($r9FailureEvidence,$s.r9_failure_evidence_json),@($r10StabilityProtocol,$s.r10_stability_protocol_json),@($r10ImplementationEvidence,$s.r10_stability_implementation_evidence_json))){if((Get-StableSha256 $Locks $p[0]) -ne $p[1]){throw "Gate-bound evidence changed: $($p[0])"}};foreach($name in $repositoryPythonSourcePaths.Keys){$path=$repositoryPythonSourcePaths[$name];if((Get-StableSha256 $Locks $path) -ne $s.$name){throw "Gate-bound repository Python source changed: $path"}};if((Get-StableSha256 $Locks $multiSeedEvidence) -ne 'a53dfd37056fd0ea3ceeee41d25a2d953160411ac15d31df89e418e3b1b7ff97'){throw 'Integrated multi-seed implementation evidence is not the supplied SHA'};if((Get-StableSha256 $Locks $r9FailureEvidence) -ne 'd6b39f398b09b8198007feefd0f1c09b9f78c143d7adbee1568356b3d5863e79'){throw 'r9 failure evidence changed'};if((Get-StableSha256 $Locks $r10StabilityProtocol) -ne '295b943ac77145ef06cda25c76ab3113045204f8729ead6a909ef382082004b2'){throw 'r10 pre-registration evidence changed'};if((Get-StableSha256 $Locks $r10ImplementationEvidence) -ne '6e7250312834d66e0a0f92223b4648b8e3c96b291b0897963adf063cf391e2ba'){throw 'r10 implementation evidence changed'};if($LauncherSha256 -ne $s.launcher_ps1 -or $ContractSha256 -ne $s.lean_team_contract_json){throw 'Gate-bound launcher or contract changed'}
 $lockedTestEvidence=Get-StableLock $Locks $launchTestEvidence;if($Gate.launch_test_evidence.canonical_path -ne $launchTestEvidence -or $Gate.launch_test_evidence.sha256 -notmatch '^[0-9a-f]{64}$' -or $lockedTestEvidence.sha256 -ne $Gate.launch_test_evidence.sha256){throw 'Immutable r10 launch-test evidence binding failed'};$testEvidence=$lockedTestEvidence.text|ConvertFrom-Json -ErrorAction Stop
 $expectedEvidenceSources=[pscustomobject]@{launcher_ps1=$LauncherSha256;runner_sh=$RunnerSha256;test_multi_seed_py=(Get-StableSha256 $Locks $multiSeedTest);probe_pilot_progress_ps1=(Get-StableSha256 $Locks $progressProbe);probe_pilot_process_sh=(Get-StableSha256 $Locks $processProbe);r10_power_gate_smoke_ps1=(Get-StableSha256 $Locks $powerGateTest);r10_user_confirmation_gate_smoke_ps1=(Get-StableSha256 $Locks $confirmationGateTest);r10_review_binding_smoke_ps1=(Get-StableSha256 $Locks $reviewGateTest);r10_lifecycle_failure_smoke_ps1=(Get-StableSha256 $Locks $lifecycleFailureTest);r10_probe_progress_smoke_ps1=(Get-StableSha256 $Locks $probeProgressTest);r10_live_power_gate_probe_ps1=(Get-StableSha256 $Locks $livePowerProbe);r10_launch_test_evidence_smoke_ps1=(Get-StableSha256 $Locks $launchEvidenceTest);r10_stable_read_lock_smoke_ps1=(Get-StableSha256 $Locks $stableReadRaceTest);r10_import_closure_smoke_ps1=(Get-StableSha256 $Locks $importClosureTest);lean_team_contract_json=$ContractSha256;r8_verification_evidence_json=(Get-StableSha256 $Locks $r8Evidence);multi_seed_implementation_evidence_json=(Get-StableSha256 $Locks $multiSeedEvidence);r9_failure_evidence_json=(Get-StableSha256 $Locks $r9FailureEvidence);r10_stability_protocol_json=(Get-StableSha256 $Locks $r10StabilityProtocol);r10_stability_implementation_evidence_json=(Get-StableSha256 $Locks $r10ImplementationEvidence)};foreach($name in $repositoryPythonSourcePaths.Keys){$expectedEvidenceSources|Add-Member -NotePropertyName $name -NotePropertyValue (Get-StableSha256 $Locks $repositoryPythonSourcePaths[$name])}
 Assert-R10LaunchTestEvidence $testEvidence $prefix $seeds $children $expectedEvidenceSources
 Assert-R10ReviewBindings $Gate $prefix $LauncherSha256 $RunnerSha256 $ContractSha256
}
function Get-ObservedChildState { @($children|%{$executionPath=Join-Path (Join-Path (Join-Path $bulkRoot 'runs') $_) 'execution.json';[pscustomobject]@{run_id=$_;run_directory_exists=Test-Path -LiteralPath (Split-Path -Parent $executionPath);execution_exists=Test-Path -LiteralPath $executionPath}}) }
$heldReadLocks=@();$lockedFiles=@{};$markerStream=$null;$processStarted=$false
try {
 # Authorization hashes and JSON parsing are derived from one held byte array per artifact.
 $gateLock=Open-StableJsonLock $gatePath $ExpectedCanonicalGateSha256 'Canonical r10 gate';$heldReadLocks+=@($gateLock.stream)
 $confirmationLock=Open-StableJsonLock $confirmationPath $ExpectedUserConfirmationSha256 'r10 confirmation';$heldReadLocks+=@($confirmationLock.stream)
 $gateHash=$gateLock.sha256;$confirmationHash=$confirmationLock.sha256;$gate=$gateLock.data;$confirmation=$confirmationLock.data

 # FileShare.Read keeps every validated input readable but non-writable/non-replaceable through terminal validation.
 $protectedPaths=@($PSCommandPath,$runner,$contract,$cacheManifest,$validatorLog,$sourceManifest,$environmentManifest,$r8Evidence,$multiSeedEvidence,$r9FailureEvidence,$r10StabilityProtocol,$r10ImplementationEvidence,$multiSeedTest,$powerGateTest,$confirmationGateTest,$reviewGateTest,$livePowerProbe,$lifecycleFailureTest,$probeProgressTest,$launchEvidenceTest,$stableReadRaceTest,$importClosureTest,$progressProbe,$processProbe,$launchTestEvidence)+@($repositoryPythonSourcePaths.Values)
 foreach($path in $protectedPaths){$locked=Open-StableReadLock $path;$heldReadLocks+=@($locked.stream);$lockedFiles[$locked.path.ToLowerInvariant()]=$locked}
 $launcherHash=Get-StableSha256 $lockedFiles $PSCommandPath;$runnerHash=Get-StableSha256 $lockedFiles $runner;$contractHash=Get-StableSha256 $lockedFiles $contract
 Assert-R10Gate $gate $gateHash $launcherHash $runnerHash $contractHash $lockedFiles;Assert-R10UserConfirmation $confirmation $prefix $seeds $children $sourceThreadId $gateHash $launcherHash $runnerHash $contractHash

 # Immutable evidence, prior-attempt evidence, logs, and both child namespaces must be clear before consuming the permanent marker.
 foreach($path in @($stdout,$stderr,$lifecycle)+($children|%{Join-Path (Join-Path $bulkRoot 'runs') $_})){if(Test-Path -LiteralPath $path){throw "Evidence, log, or child collision before marker: $path"}}
 if(Test-Path -LiteralPath $marker){throw 'An r10 attempt marker already exists; refusing every later invocation'}
 New-Item -ItemType Directory -Path $logRoot -Force|Out-Null
 try {$markerStream=[IO.File]::Open($marker,[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}catch [IO.IOException]{throw 'An r10 attempt marker already exists; refusing every later invocation'}
 try {
  Write-Lifecycle @{event='attempt_created';run_id_prefix=$prefix;children=$children;seeds=$seeds;canonical_gate_sha256=$gateHash;user_confirmation_sha256=$confirmationHash;launcher_sha256=$launcherHash;runner_sha256=$runnerHash;contract_sha256=$contractHash;attempt_marker=$marker}
  $gpu=Get-CimInstance Win32_VideoController|?{$_.Name -match 'NVIDIA'}|select -First 1;if(!$gpu -or $gpu.DriverVersion -ne '32.0.16.1047' -or $gpu.Status -ne 'OK'){throw 'NVIDIA 610.47 gate failed'};if((Get-PSDrive C).Free/1GB -lt [double]$gate.storage_gate.c_minimum_gib -or (Get-PSDrive E).Free/1GB -lt [double]$gate.storage_gate.e_minimum_gib){throw 'Storage gate failed'}
  $events=@((Get-StableText $lockedFiles $validatorLog)-split '\r?\n'|%{if(![string]::IsNullOrWhiteSpace($_)){try{$_|ConvertFrom-Json -ErrorAction Stop}catch{}}}|?{$_.status});$v=$events|select -Last 1;$cacheHash=Get-StableSha256 $lockedFiles $cacheManifest;$validatorHash=Get-StableSha256 $lockedFiles $validatorLog;if(!$v -or $v.status -ne 'valid' -or $v.cache_manifest_sha256 -ne $cacheHash -or $gate.cache_gate.sha256 -ne $cacheHash -or $gate.cache_gate.validator_v2_log_sha256 -ne $validatorHash){throw 'Cache validator gate failed'}
  $existing=Get-CimInstance Win32_Process|?{$_.ProcessId -ne $PID -and $_.CommandLine -and ($_.CommandLine -match 'paper_faithful\.training\.cli (pilot|multi-seed-pilot)' -or $_.CommandLine -match 'run_paper_text_(pilot|multiseed)')};$wsl=@(& wsl.exe -d Ubuntu -e bash --noprofile --norc -lc "pgrep -af '[p]aper_faithful.training.cli (pilot|multi-seed-pilot)' || true");if($existing -or $wsl){throw 'A single-pilot or multi-seed process already exists'};$power=Get-StableAcPowerFacts
  Write-Lifecycle @{event='launch_requested';run_id_prefix=$prefix;children=$children;seeds=$seeds;stable_ac_power=$power}
  $p=Start-Process -FilePath "$env:SystemRoot\System32\wsl.exe" -ArgumentList @('-d','Ubuntu','-e','bash','--noprofile','--norc','./paper_faithful/training/run_paper_text_multiseed_smoke_r10.sh') -WorkingDirectory $projectRoot -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru;$processStarted=$true
 } catch {if(!$processStarted){Write-Lifecycle @{event='prelaunch_failed';run_id_prefix=$prefix;reason=$_.Exception.Message;child_state=(Get-ObservedChildState)}};throw}

 $processError=$null
 try {Write-Lifecycle @{event='process_started';run_id_prefix=$prefix;process_id=$p.Id};$p.WaitForExit();$scriptExitCode=$p.ExitCode}catch{$processError=$_}finally{try{if(!$p.HasExited){$p.WaitForExit()};$scriptExitCode=$p.ExitCode}catch{if($null -eq $processError){$processError=$_}};$rawChildren=Get-ObservedChildState;Write-Lifecycle @{event='process_exited';run_id_prefix=$prefix;process_id=$p.Id;exit_code=$scriptExitCode;stdout_exists=(Test-Path -LiteralPath $stdout);stderr_exists=(Test-Path -LiteralPath $stderr);stdout_bytes=$(if(Test-Path -LiteralPath $stdout){(Get-Item -LiteralPath $stdout).Length}else{$null});stderr_bytes=$(if(Test-Path -LiteralPath $stderr){(Get-Item -LiteralPath $stderr).Length}else{$null});child_state=$rawChildren}}
 try {if($null -ne $processError){throw $processError};$terminal=$null;foreach($line in @(Get-Content -LiteralPath $stdout -ErrorAction SilentlyContinue)){try{$candidate=$line|ConvertFrom-Json;if($candidate.status){$terminal=$candidate}}catch{}};if($scriptExitCode -ne 0 -or !$terminal -or $terminal.status -ne 'completed' -or $terminal.mode -ne 'multi-seed-pilot' -or @($terminal.children).Count -ne 2){throw 'Runner did not return a completed two-child terminal JSON'};for($i=0;$i -lt 2;$i++){if($terminal.children[$i].run_id -ne $children[$i] -or $terminal.children[$i].verification.status -ne 'verified'){throw 'Terminal child verification binding failed'}};$childExecutions=Get-ObservedChildState;if(@($childExecutions|?{-not $_.execution_exists}).Count){throw 'A terminal child is missing execution.json'};Write-Lifecycle @{event='terminal_validated';run_id_prefix=$prefix;process_id=$p.Id;exit_code=$scriptExitCode;terminal_children=$terminal.children;child_state=$childExecutions}}catch{Write-Lifecycle @{event='terminal_validation_failed';run_id_prefix=$prefix;process_id=$p.Id;exit_code=$scriptExitCode;reason=$_.Exception.Message;child_state=(Get-ObservedChildState)};throw}
} finally {
 if($null -ne $markerStream){$markerStream.Dispose()}
 $disposeError=$null;for($index=$heldReadLocks.Count-1;$index -ge 0;$index--){try{$heldReadLocks[$index].Dispose()}catch{if($null -eq $disposeError){$disposeError=$_}}};if($null -ne $disposeError){throw $disposeError}
}
exit $scriptExitCode
